glut_desc = heav[is_glut[heav]]
ng_desc = heav[~is_glut[heav]]
assert len(glut_desc) == 19 and len(ng_desc) == 58
GI = 1110
assert int(ng_desc[24]) == GI and int(ng_desc[25]) == 319

keep_wA = keep_new.copy()
