keep_25 = keep_new.copy()
keep_25[np.sort(ng_desc[:25])] = False
emask_wA = keep_wA[src_all] & keep_wA[dst_all]
emask_25 = keep_25[src_all] & keep_25[dst_all]
assert int(keep_wA.sum()) == 21785 and int(emask_wA.sum()) == 644177
