def mass(E, src_mask=None, dst_mask=None):
    m = E.copy()
    if src_mask is not None:
        m &= src_mask[src_all]
    if dst_mask is not None:
        m &= dst_mask[dst_all]
    return float(np.abs(vals_all[m]).sum())


